const listWorkspacesByUser = `-- name: ListWorkspacesByUser :many

SELECT w.id, w.slug, w.name, w.created_at,
       (w.personal_user_id IS NOT DISTINCT FROM m.user_id) AS is_personal,
       (SELECT count(*) FROM forms f WHERE f.workspace_id = w.id)::bigint AS form_count
FROM workspace_members m
JOIN workspaces w ON w.id = m.workspace_id
WHERE m.user_id = $1
ORDER BY w.created_at ASC
`

type ListWorkspacesByUserRow struct {
	ID         uuid.UUID
	Slug       string
	Name       string
	CreatedAt  pgtype.Timestamptz
	IsPersonal bool
	FormCount  int64
}

// Запросы модуля workspaces. Схема — migrations/0002_auth (таблицы workspaces,
// workspace_members). Генерация: `make sqlc`.
// Пространства, в которых состоит пользователь. JOIN через workspace_members:
// возвращаются только пространства с членством (инвариант доступа — id из URL
// права не даёт). Личное создаётся регистрацией и всегда первое: сортировка по
// created_at ставит его в начало, потому что оно старше любого другого.
//
// is_personal вычисляется сравнением с personal_user_id, а не отдаётся сырым:
// кабинету важно «личное ли оно ДЛЯ МЕНЯ», а не чьё оно вообще. IS NOT DISTINCT
// FROM, а не «=»: у неличного пространства personal_user_id равен NULL, и
// обычное сравнение дало бы NULL вместо false — то есть непустой bool в Go.
//
// form_count — сколько форм в пространстве (подпись рядом с названием в обзоре).
// Подзапрос, а не второй поход в forms: обзор рисует ВСЕ пространства разом, и
// отдельный запрос на каждое был бы N+1 ради одного числа. Мягкого удаления у
// форм нет — считаются все строки, включая черновики.
func (q *Queries) ListWorkspacesByUser(ctx context.Context, userID uuid.UUID) ([]ListWorkspacesByUserRow, error) {
	rows, err := q.db.Query(ctx, listWorkspacesByUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWorkspacesByUserRow
	for rows.Next() {
		var i ListWorkspacesByUserRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.CreatedAt,
			&i.IsPersonal,
			&i.FormCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockFormForSubmit = `-- name: LockFormForSubmit :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// Транзакционный advisory-lock по форме для жёсткого капа лимита ответов (фаза 8.5
// шаг 4, ADR §10): сериализует конкурентные приёмы ОДНОЙ формы, поэтому счёт
// «сколько уже принято» точен и перебор невозможен. Блокировку берёт ТОЛЬКО путь с
// заданным лимитом; форма без лимита пишется без неё (contention только у формы у
// предела). Ключ — хеш form_id (коллизия хешей лишь изредка сериализует две разные
// формы — безвредно). xact-версия сама снимается на commit/rollback.
func (q *Queries) LockFormForSubmit(ctx context.Context, dollar_1 string) error {
	_, err := q.db.Exec(ctx, lockFormForSubmit, dollar_1)
	return err
}

const lockIdentities = `-- name: LockIdentities :many
SELECT provider FROM user_identities WHERE user_id = $1 ORDER BY provider FOR UPDATE
`

// Привязки аккаунта под блокировкой — гейт отвязки «останется ли способ войти».
//
// Мина: FOR UPDATE здесь несущий, а не украшение. Гейт читает состав и решает
// по нему, поэтому без блокировки две одновременные отвязки разных провайдеров
// обе видят «привязок две», обе проходят проверку и обе удаляют — аккаунт без
// пароля остаётся без единого способа войти, и чинится это только руками в БД.
// Под блокировкой второй запрос ждёт первого и перечитывает состав уже без
// удалённой строки.
//
// count(*) вместо списка не годится: агрегат с FOR UPDATE Postgres не
// принимает, а считать строки в Go — ровно та же цена при одном-двух
// провайдерах. ORDER BY — детерминированный порядок захвата.
func (q *Queries) LockIdentities(ctx context.Context, userID uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, lockIdentities, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var provider string
		if err := rows.Scan(&provider); err != nil {
			return nil, err
		}
		items = append(items, provider)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

